  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SP113-1-38' AND q.question IS NOT DISTINCT FROM $swsi$依據國民年金法規定，當隔代教養之服務家庭，被保險人案祖父或祖母身亡且無其他親屬，下列 被扶養之孫子女，何者無法請領遺屬年金給付？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$19 歲高中畢業後，擔任汽修技師培訓人員每月賺取基本工資之收入$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$21 歲正就讀大學，在加油站打工每月賺取未達基本工資之收入$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$23 歲正就讀研究所，擔任家教與餐飲店打工，每月賺取未達基本工資之收入$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$應受被保險人扶養而無謀生能力者$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$ AND q.exp_why IS NULL AND q.analysis_status = 'pending') THEN RAISE EXCEPTION 'SP113-1-38 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SP113-1-39' AND q.question IS NOT DISTINCT FROM $swsi$依據長期照顧服務法規定，有關長照服務提供方式之敘述，下列何者正確？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$按民眾獨居狀況核定其長照需要等級$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$按民眾失能程度核定自行負擔的額度$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$長照服務提供方式分為居家式、社區式、機構住宿式及家庭照顧者支持服務$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$低收入戶要負擔一定比例的自付費用$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$C$swsi$ AND q.exp_why IS NULL AND q.analysis_status = 'pending') THEN RAISE EXCEPTION 'SP113-1-39 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SP113-1-40' AND q.question IS NOT DISTINCT FROM $swsi$依據長期照顧服務機構法人條例，長照機構法人之董事會至少多久時間須召開 1 次會議？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$至少 3 個月 1 次$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$至少 6 個月 1 次$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$至少 1 年 1 次$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$至少 2 年 3 次$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$B$swsi$ AND q.exp_why IS NULL AND q.analysis_status = 'pending') THEN RAISE EXCEPTION 'SP113-1-40 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-105-2-25' AND q.question IS NOT DISTINCT FROM $swsi$每一門專業都有其核心的社會使命要去完成，有關Morales & Sheafor（1998）提出的社會工 作存在的三個使命（3C’s），下列何者正確？①照顧（caring）②改變社會（changing the society）③慈善（charity）④治療（curing）$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$①②③$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$①②④$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$①③④$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$②③④$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$B$swsi$ AND q.exp_why IS NULL AND q.analysis_status = 'pending') THEN RAISE EXCEPTION 'SW-105-2-25 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-106-1-40' AND q.question IS NOT DISTINCT FROM $swsi$下列何者非家庭暴力防治法所規定之家庭成員?$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$不同住之女婿$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$不同住之前夫$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$不同住之堂外甥$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$同住之子女$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$C$swsi$ AND q.exp_why IS NULL AND q.analysis_status = 'pending') THEN RAISE EXCEPTION 'SW-106-1-40 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-108-2-01' AND q.question IS NOT DISTINCT FROM $swsi$臺灣社會工作專業發展過程有很多有意義的首次，下列何者錯誤？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$臺灣世界展望會是臺灣第一個聘用社會工作員的民間社福單位$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$臺灣最早聘用社會工作員的是醫院$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$臺灣社會工作員制度法制化文字出現於1976 年「中華民國臺灣經濟建設六年計畫」$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$1971 年政府通過設置社會工作員實驗計畫，聘用10 名社會工作員，負責平價住宅業務$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$社會工作專業$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$歷史發展 > 台灣社工首次$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$台灣社工, 世界展望會, 平價住宅, 社工員實驗計畫, 醫院$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(A)錯誤：台灣最早聘用社工員的是『醫院』，並非『世界展望會』為第一個聘社工員的民間單位。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(B)最早聘社工員是醫院、(C)社工員制度法制化文字1976出現於經建六年計畫、(D)1971政府設社工員實驗計畫聘10名負責平價住宅——皆正確。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$台灣最早社工員＝醫院(台大醫院社會服務)。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$台灣社工史：戰後救濟院→1960年代社工教育(初附屬社會學系非獨立學門)→1971社工員實驗計畫(平價住宅)→社工員制度法制化→1997社工師法(4/2社工日)→2008修法設專科社工師。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$社會工作史(台灣社工首次)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$) THEN RAISE EXCEPTION 'SW-108-2-01 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-109-1-05' AND q.question IS NOT DISTINCT FROM $swsi$在刑事司法領域中，社會工作的工作範圍涵蓋相當廣泛，有關犯罪相關理論之敘述，下列何者正 確？①個人化理論認為罪犯是社會的受害者，認為社會需要改變 ②社會學觀點認為個人需要對 犯罪行為負責，但是結構性的社會問題亦需要解決 ③嚇阻理論認為犯罪者無法自制，可以運用 懲罰阻止犯罪 ④生物決定論認為犯罪者是遺傳造成，無法自制，因此要監禁犯罪者 ⑤行為主 義認為偏差和犯罪行為是不當的學習反應$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$①③④$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$②③④$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$①②③$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$②④⑤$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$D$swsi$ AND q.exp_why IS NULL AND q.analysis_status = 'pending') THEN RAISE EXCEPTION 'SW-109-1-05 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-110-1-33' AND q.question IS NOT DISTINCT FROM $swsi$關於身心障礙的敘述，下列何者正確？①障礙的分類是固定不變的 ②中世紀歐洲因慈善理念進行貧民與障礙者的分類收容救濟，是將障礙者機構化的第一步 ③文藝復興時期的歐洲開始將貧窮與障礙議題分開處理 ④19 世紀啟蒙時代視障礙者為病人的醫療觀點，讓障礙者逐漸被社會所排除 ⑤1950 年代機構式缺乏人性的照顧機制備受關注，開始西方的去機構化運動$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$①②③$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$②④⑤$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$①③⑤$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$③④⑤$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$D$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$障礙者服務$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$身障歷史 > 身障觀點演變$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$身心障礙, 機構化, 去機構化, 醫療觀點, 文藝復興$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(D)③④⑤：③文藝復興時期開始將貧窮與障礙議題分開處理④19世紀啟蒙時代視障礙者為病人的醫療觀點⑤(相關正確敘述)。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$①障礙的分類『固定不變』＝錯(分類隨時代文化變動);②關於中世紀分類收容是『機構化第一步』的敘述不正確。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$障礙分類隨時代文化『變動』(非固定不變)。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$身障史:分類隨時代變動;文藝復興將貧窮與障礙分開;19世紀醫療觀點視為病人。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$身心障礙(障礙歷史)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$) THEN RAISE EXCEPTION 'SW-110-1-33 修正後內容不符，取消'; END IF;
  IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN ('DS-104-1-25', 'DS-106-1-10', 'DS-106-1-37', 'DS-109-2-23', 'DS-110-2-14', 'DS-115-1-18', 'DS-115-1-22', 'R-105-1-24', 'R-106-2-01', 'R-106-2-02', 'R-113-2-30', 'SP106-2-25', 'SP106-2-35', 'SP111-2-37', 'SP113-1-30', 'SP113-1-31', 'SP113-1-32', 'SP113-1-33', 'SP113-1-34', 'SP113-1-35', 'SP113-1-37', 'SP113-1-38', 'SP113-1-39', 'SP113-1-40', 'SW-105-2-25', 'SW-106-1-40', 'SW-108-2-01', 'SW-109-1-05', 'SW-110-1-33') AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION '有其他題目被改到，取消'; END IF;
  IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN ('DS-104-1-25', 'DS-106-1-10', 'DS-106-1-37', 'DS-109-2-23', 'DS-110-2-14', 'DS-115-1-18', 'DS-115-1-22', 'R-105-1-24', 'R-106-2-01', 'R-106-2-02', 'R-113-2-30', 'SP106-2-25', 'SP106-2-35', 'SP111-2-37', 'SP113-1-30', 'SP113-1-31', 'SP113-1-32', 'SP113-1-33', 'SP113-1-34', 'SP113-1-35', 'SP113-1-37', 'SP113-1-38', 'SP113-1-39', 'SP113-1-40', 'SW-105-2-25', 'SW-106-1-40', 'SW-108-2-01', 'SW-109-1-05', 'SW-110-1-33') AND ((b.row->'answer') IS DISTINCT FROM (to_jsonb(q)->'answer') OR (b.row->'accepted_answers') IS DISTINCT FROM (to_jsonb(q)->'accepted_answers') OR (b.row->'grading_mode') IS DISTINCT FROM (to_jsonb(q)->'grading_mode'))) THEN RAISE EXCEPTION '答案或給分被改到，取消'; END IF;
